/-
# Perfect Numbers: Definitions and Basic Properties

This module establishes fundamental properties of perfect numbers using Mathlib's
`Nat.Perfect` and divisor-sum arithmetic function `σ`.
-/
import Mathlib

open ArithmeticFunction Finset Nat

/-! ## Basic properties of perfect numbers -/

/-
A perfect number is at least 2.
-/
theorem Nat.Perfect.one_lt {n : ℕ} (h : n.Perfect) : 1 < n := by
  rcases n with ( _ | _ | n ) <;> simp_all +arith +decide [ Nat.Perfect ]

/-
No prime is perfect.
-/
theorem Nat.Perfect.not_prime {n : ℕ} (h : n.Perfect) : ¬ n.Prime := by
  grind +suggestions

/-! ## Concrete examples -/

/-- 6 is perfect. -/
theorem perfect_six : Nat.Perfect 6 := by
  constructor
  · native_decide
  · norm_num

/-- 28 is perfect. -/
theorem perfect_28 : Nat.Perfect 28 := by
  constructor
  · native_decide
  · norm_num

/-- 496 is perfect. -/
theorem perfect_496 : Nat.Perfect 496 := by
  constructor
  · native_decide
  · norm_num

/-- 8128 is perfect. -/
theorem perfect_8128 : Nat.Perfect 8128 := by
  constructor
  · native_decide
  · norm_num

/-! ## Relationship between σ₁ and Perfect -/

/-
A positive `n` is perfect iff `σ₁(n) = 2n`.
-/
theorem perfect_iff_sigma_eq {n : ℕ} (hn : 0 < n) :
    n.Perfect ↔ (ArithmeticFunction.sigma 1) n = 2 * n := by
      rw [ perfect_iff_sum_divisors_eq_two_mul hn ];
      rw [ ArithmeticFunction.sigma_one_apply ]

/-! ## Euclid's theorem: Mersenne primes yield even perfect numbers -/

/-
**Euclid's Theorem.** If `2^p - 1` is prime, then `2^(p-1) * (2^p - 1)` is perfect.
-/
theorem euclid_perfect {p : ℕ} (hp : 1 ≤ p) (hm : (2 ^ p - 1).Prime) :
    Nat.Perfect (2 ^ (p - 1) * (2 ^ p - 1)) := by
      -- We need to show 2^(p-1) * (2^p - 1) is perfect, i.e., σ₁(n) = 2n.
      have h_sigma : ∑ i ∈ Nat.divisors (2 ^ (p - 1) * (2 ^ p - 1)), i = 2 * (2 ^ (p - 1) * (2 ^ p - 1)) := by
        -- By multiplicativity of σ₁, we have σ₁(n) = σ₁(2^(p-1)) * σ₁(2^p - 1).
        have h_sigma_mult : ∑ i ∈ Nat.divisors (2 ^ (p - 1) * (2 ^ p - 1)), i = (∑ i ∈ Nat.divisors (2 ^ (p - 1)), i) * (∑ i ∈ Nat.divisors (2 ^ p - 1), i) := by
          have h_sigma_mul : ∀ {a b : ℕ}, Nat.gcd a b = 1 → ∑ i ∈ Nat.divisors (a * b), i = (∑ i ∈ Nat.divisors a, i) * (∑ i ∈ Nat.divisors b, i) := by
            exact?;
          rcases p with ( _ | _ | p ) <;> simp_all +decide [ Nat.one_le_iff_ne_zero, parity_simps ];
        rcases p with ( _ | _ | p ) <;> simp_all +decide [ Nat.geomSum_eq ];
        zify ; norm_num ; ring;
      simp_all +decide [ Nat.Perfect, Nat.sum_divisors_eq_sum_properDivisors_add_self ];
      exact ⟨ by linarith, by linarith ⟩

/-! ## Even perfect numbers are of Euclid's form -/

/-
Every even perfect number is of the form `2^(p-1) * (2^p - 1)` with `2^p - 1` prime.
-/
theorem even_perfect_classification {n : ℕ} (hperf : n.Perfect) (heven : Even n) :
    ∃ p : ℕ, Nat.Prime (2 ^ p - 1) ∧ n = 2 ^ (p - 1) * (2 ^ p - 1) := by
      -- Write n = 2^a * m where m is odd and a ≥ 1
      obtain ⟨a, m, ha, hm⟩ : ∃ a m, n = 2^a * m ∧ Odd m ∧ a ≥ 1 := by
        -- Let $a$ be the largest integer such that $2^a$ divides $n$.
        obtain ⟨a, ha⟩ : ∃ a, 2^a ∣ n ∧ ¬2^(a+1) ∣ n := by
          exact ⟨ Nat.factorization n 2, Nat.ordProj_dvd _ _, Nat.pow_succ_factorization_not_dvd ( by rintro rfl; simp_all +decide [ Nat.Perfect ] ) ( by decide ) ⟩;
        cases' ha.1 with m hm;
        exact ⟨ a, m, hm, Nat.odd_iff.mpr ( Nat.mod_two_ne_zero.mp fun contra => ha.2 <| hm.symm ▸ Nat.mul_dvd_mul_left _ ( Nat.dvd_of_mod_eq_zero contra ) ), Nat.pos_of_ne_zero fun h => by simp_all +decide [ Nat.Perfect, even_iff_two_dvd ] ⟩;
      -- Since n is perfect, we have σ₁(n) = 2n. Using the multiplicative property of σ₁, we get σ₁(2^a * m) = σ₁(2^a) * σ₁(m) = (2^(a+1) - 1) * σ₁(m).
      have h_sigma : (2^(a+1) - 1) * ∑ d ∈ Nat.divisors m, d = 2^(a+1) * m := by
        have h_sigma : ∑ d ∈ Nat.divisors (2^a * m), d = (∑ d ∈ Nat.divisors (2^a), d) * (∑ d ∈ Nat.divisors m, d) := by
          have h_sigma_mul : ∀ {x y : ℕ}, Nat.gcd x y = 1 → ∑ d ∈ Nat.divisors (x * y), d = (∑ d ∈ Nat.divisors x, d) * (∑ d ∈ Nat.divisors y, d) := by
            grind +suggestions;
          cases a <;> cases hm.1 <;> aesop;
        simp_all +decide [ Nat.geomSum_eq, Nat.Perfect, Nat.sum_divisors_eq_sum_properDivisors_add_self ];
        exact h_sigma ▸ by ring;
      -- Since $2^{a+1} - 1$ divides $2^{a+1} * m$, it must also divide $m$. Let $m = (2^{a+1} - 1) * k$ for some integer $k$.
      obtain ⟨k, hk⟩ : ∃ k, m = (2^(a+1) - 1) * k := by
        exact ( Nat.Coprime.dvd_of_dvd_mul_left ( show Nat.Coprime ( 2 ^ ( a + 1 ) - 1 ) ( 2 ^ ( a + 1 ) ) by simp +decide [ Nat.one_le_iff_ne_zero, parity_simps ] ) <| h_sigma ▸ dvd_mul_right _ _ );
      rcases k with ( _ | _ | k ) <;> simp_all +decide [ Nat.Perfect, Nat.sum_divisors_eq_sum_properDivisors_add_self ];
      · use a + 1;
        simp_all +decide [ Nat.prime_def_lt' ];
        exact ⟨ Nat.le_sub_one_of_lt ( lt_self_pow₀ ( by decide ) ( Nat.succ_lt_succ hm.2 ) ), fun m hm₁ hm₂ hm₃ => by have := Nat.mem_properDivisors.mpr ⟨ hm₃, hm₂ ⟩ ; nlinarith [ Nat.sub_add_cancel ( Nat.one_le_pow ( a + 1 ) 2 ( by decide ) ), Finset.single_le_sum ( fun x _ => Nat.zero_le x ) this ] ⟩;
      · -- Since $k + 2$ is a divisor of $m$, we have $\sum_{x \in \text{proper divisors}(m)} x \geq 1 + (k + 2)$.
        have h_divisors : ∑ x ∈ Nat.properDivisors ((2^(a+1) - 1) * (k + 2)), x ≥ 1 + (k + 2) := by
          have h_divisors : Nat.properDivisors ((2^(a+1) - 1) * (k + 2)) ⊇ {1, k + 2} := by
            simp +decide [ Finset.insert_subset_iff ];
            exact ⟨ by nlinarith only [ Nat.le_sub_one_of_lt ( Nat.pow_lt_pow_right ( by decide : 1 < 2 ) ( by linarith : a + 1 > 1 ) ) ], lt_tsub_iff_left.mpr ( by linarith [ Nat.pow_le_pow_right ( by decide : 1 ≤ 2 ) ( by linarith : a + 1 ≥ 2 ) ] ) ⟩;
          exact le_trans ( by rw [ Finset.sum_pair ] ; linarith ) ( Finset.sum_le_sum_of_subset h_divisors );
        nlinarith [ Nat.sub_add_cancel ( Nat.one_le_pow ( a + 1 ) 2 zero_lt_two ), pow_pos ( zero_lt_two' ℕ ) a, pow_succ' 2 a, mul_le_mul_left' ( Nat.one_le_pow ( a + 1 ) 2 zero_lt_two ) k ]

/-! ## Parity properties relevant to odd perfect numbers -/

/-
6 is the smallest perfect number.
-/
theorem perfect_ge_six {n : ℕ} (h : n.Perfect) : 6 ≤ n := by
  contrapose! h; interval_cases n <;> simp_all +decide [ Nat.Perfect ] ;

/-- Every perfect number is at least 2. (Alternate statement using `pos`.) -/
theorem perfect_pos {n : ℕ} (h : n.Perfect) : 0 < n :=
  h.2

