/-
# Euler's Shape Theorem for Odd Perfect Numbers

Euler proved in 1747 that if an odd perfect number exists, it must have the form
`q^(4k+1) * m²` where `q ≡ 1 (mod 4)` is prime and `gcd(q, m) = 1`.
-/
import Mathlib
import PerfectNumbers.Defs

open ArithmeticFunction Finset Nat

/-! ## Helper lemmas on σ₁ parity -/

/-
For an odd prime `p`, σ₁(p^a) is odd ↔ a is even.
-/
theorem sigma_one_prime_pow_odd_iff {p a : ℕ} (hp : p.Prime) (hodd_p : Odd p) :
    Odd ((ArithmeticFunction.sigma 1) (p ^ a)) ↔ Even a := by
      -- By definition of sigma, we have σ₁(p^a) = 1 + p + p² + ... + p^a.
      have h_sigma_def : (ArithmeticFunction.sigma 1) (p ^ a) = ∑ i ∈ Finset.range (a + 1), p ^ i := by
        simp +decide [ ArithmeticFunction.sigma, Nat.divisors_prime_pow hp ];
      simp_all +decide [ Finset.sum_nat_mod, Nat.even_iff, Nat.odd_iff, Nat.pow_mod ];
      constructor <;> intro <;> omega

/-
σ₁(p^a) for odd exponent a = 2j+1 factors as (1+p) * Σ p^(2i).
-/
theorem sigma_one_odd_exp_factor {p j : ℕ} (hp : p.Prime) :
    (ArithmeticFunction.sigma 1) (p ^ (2 * j + 1)) =
      (1 + p) * ∑ i ∈ Finset.range (j + 1), p ^ (2 * i) := by
        simp +decide [ *, Nat.divisors_prime_pow, Nat.geomSum_eq, ArithmeticFunction.sigma_apply_prime_pow ];
        induction j <;> simp_all +decide [ Nat.mul_succ, pow_succ', Finset.sum_range_succ ] ; ring

/-
If q ≡ 3 (mod 4), then 4 ∣ σ₁(q^(2j+1)).
-/
theorem sigma_one_mod3_val2 {q j : ℕ} (hq : q.Prime) (hmod : q % 4 = 3) :
    4 ∣ (ArithmeticFunction.sigma 1) (q ^ (2 * j + 1)) := by
      -- By sigma_one_odd_exp_factor, σ₁(q^(2j+1)) = (1+q) * T.
      have h_sigma_factor : (ArithmeticFunction.sigma 1) (q ^ (2 * j + 1)) = (1 + q) * ∑ i ∈ Finset.range (j + 1), q ^ (2 * i) := by
        exact?;
      exact h_sigma_factor.symm ▸ dvd_mul_of_dvd_left ( Nat.dvd_of_mod_eq_zero ( by norm_num [ Nat.add_mod, Nat.pow_mod, hmod ] ) ) _

/-! ## Key structural lemma: odd number with all even exponents is a perfect square -/

/-
If every prime factor of n has even multiplicity, then n is a perfect square.
-/
theorem eq_sq_of_even_factorization {n : ℕ} (hn : n ≠ 0)
    (heven : ∀ p : ℕ, p.Prime → (n.factorization p) % 2 = 0) :
    ∃ m : ℕ, n = m ^ 2 := by
      exact ⟨ ∏ p ∈ n.primeFactors, p ^ ( n.factorization p / 2 ), by nth_rw 1 [ ← Nat.factorization_prod_pow_eq_self hn ] ; exact Eq.symm <| by rw [ ← Finset.prod_pow ] ; exact Finset.prod_congr rfl fun p hp ↦ by rw [ ← pow_mul, Nat.div_mul_cancel <| Nat.dvd_of_mod_eq_zero <| heven p <| Nat.prime_of_mem_primeFactors hp ] ⟩

/-
Removing one prime power factor from n. If n = q^e * r with gcd(q^e, r) = 1,
    and every prime in r has even exponent, then r is a perfect square coprime to q.
-/
theorem coprime_sq_of_factorization {n q : ℕ} (hn : n ≠ 0) (hq : q.Prime)
    (heven_others : ∀ p : ℕ, p.Prime → p ≠ q → (n.factorization p) % 2 = 0) :
    ∃ m : ℕ, n = q ^ (n.factorization q) * m ^ 2 ∧ Nat.Coprime q m := by
      use (∏ p ∈ ( n.primeFactors \ { q } ), p ^ ((n.factorization p) / 2));
      constructor;
      · conv_lhs => rw [ ← Nat.factorization_prod_pow_eq_self hn ];
        rw [ ← Finset.prod_pow ];
        rw [ Finsupp.prod_of_support_subset ];
        case s => exact { q } ∪ n.primeFactors \ { q };
        · rw [ Finset.prod_union ] <;> norm_num;
          exact Or.inl ( Finset.prod_congr rfl fun x hx => by rw [ ← pow_mul, Nat.div_mul_cancel ( Nat.dvd_of_mod_eq_zero ( heven_others x ( Nat.prime_of_mem_primeFactors ( Finset.mem_sdiff.mp hx |>.1 ) ) ( by aesop ) ) ) ] );
        · aesop_cat;
        · aesop;
      · exact Nat.Coprime.prod_right fun p hp => Nat.Coprime.pow_right _ <| hq.coprime_iff_not_dvd.mpr fun h => by have := Nat.prime_dvd_prime_iff_eq hq ( Nat.prime_of_mem_primeFactors <| Finset.mem_sdiff.mp hp |>.1 ) ; aesop;

/-! ## The 2-adic valuation argument -/

/-
For an odd perfect number, exactly one prime factor has odd exponent in the factorization.
    Moreover, that prime is ≡ 1 (mod 4) and its exponent is ≡ 1 (mod 4).
-/
set_option maxHeartbeats 800000 in
theorem odd_perfect_unique_special_prime {n : ℕ}
    (hperf : Nat.Perfect n) (hodd : Odd n) :
    ∃ q : ℕ, q.Prime ∧ q ∣ n ∧
      q % 4 = 1 ∧
      (n.factorization q) % 4 = 1 ∧
      (∀ p : ℕ, p.Prime → p ∣ n → p ≠ q → (n.factorization p) % 2 = 0) := by
        -- Let $q$ be a prime factor of $n$ with an odd exponent in the factorization.
        obtain ⟨q, hq₁, hq₂⟩ : ∃ q : ℕ, Nat.Prime q ∧ q ∣ n ∧ Odd (n.factorization q) ∧ ∀ p : ℕ, Nat.Prime p → p ∣ n → p ≠ q → Even (n.factorization p) := by
          -- By definition of perfect numbers, this product equals $2n$, which has $2$-adic valuation $1$.
          have h_val2 : (Nat.factorization (∏ p ∈ n.primeFactors, (ArithmeticFunction.sigma 1 (p ^ (n.factorization p))))) 2 = 1 := by
            have h_val2 : (∏ p ∈ n.primeFactors, (ArithmeticFunction.sigma 1 (p ^ (n.factorization p)))) = 2 * n := by
              have h_sigma_mul : (ArithmeticFunction.sigma 1) n = ∏ p ∈ n.primeFactors, (ArithmeticFunction.sigma 1) (p ^ (n.factorization p)) := by
                have h_sigma_factorization : ∀ {m : ℕ}, m ≠ 0 → (ArithmeticFunction.sigma 1) m = ∏ p ∈ m.primeFactors, (ArithmeticFunction.sigma 1) (p ^ (m.factorization p)) := by
                  intros m hm_nonzero
                  have h_sigma_factorization : (ArithmeticFunction.sigma 1 m) = ∏ p ∈ m.primeFactors, (ArithmeticFunction.sigma 1 (p ^ (m.factorization p))) := by
                    have h_mul : ∀ {a b : ℕ}, a ≠ 0 → b ≠ 0 → Nat.Coprime a b → (ArithmeticFunction.sigma 1 (a * b)) = (ArithmeticFunction.sigma 1 a) * (ArithmeticFunction.sigma 1 b) := by
                      intros a b ha hb hab_coprime
                      simp [ArithmeticFunction.sigma, hab_coprime];
                      exact?
                    conv_lhs => rw [ ← Nat.factorization_prod_pow_eq_self hm_nonzero ];
                    -- Apply the multiplicativity of the sum of divisors function to each prime factor of $m$.
                    have h_sigma_factorization : ∀ {S : Finset ℕ} {f : ℕ → ℕ}, (∀ p ∈ S, Nat.Prime p) → (ArithmeticFunction.sigma 1 (∏ p ∈ S, p ^ f p)) = ∏ p ∈ S, (ArithmeticFunction.sigma 1 (p ^ f p)) := by
                      intros S f hf; induction S using Finset.induction <;> simp_all +decide ;
                      rw [ h_mul ( pow_ne_zero _ hf.1.ne_zero ) ( Finset.prod_ne_zero_iff.mpr fun p hp => pow_ne_zero _ ( Nat.Prime.ne_zero ( hf.2 p hp ) ) ) ];
                      · aesop;
                      · exact Nat.Coprime.prod_right fun p hp => Nat.Coprime.pow _ _ <| hf.1.coprime_iff_not_dvd.mpr fun h => ‹¬_› <| by have := Nat.prime_dvd_prime_iff_eq hf.1 ( hf.2 p hp ) ; aesop;
                    exact h_sigma_factorization fun p hp => Nat.prime_of_mem_primeFactors hp;
                  exact h_sigma_factorization;
                exact h_sigma_factorization hodd.pos.ne';
              exact h_sigma_mul ▸ perfect_iff_sigma_eq ( Nat.pos_of_ne_zero hodd.pos.ne' ) |>.1 hperf;
            rw [ h_val2, Nat.factorization_mul ] <;> norm_num [ hodd.pos.ne' ];
            exact Nat.factorization_eq_zero_of_not_dvd ( by simpa [ ← even_iff_two_dvd ] using hodd );
          -- Since $v_2(2n) = 1$, there must be exactly one prime factor $q$ of $n$ such that $v_2(\sigma_1(q^{n.factorization q})) = 1$.
          obtain ⟨q, hq₁, hq₂⟩ : ∃ q ∈ n.primeFactors, (Nat.factorization (ArithmeticFunction.sigma 1 (q ^ (n.factorization q)))) 2 = 1 := by
            rw [ Nat.factorization_prod ] at h_val2;
            · by_cases h₂ : ∃ q ∈ n.primeFactors, (Nat.factorization (ArithmeticFunction.sigma 1 (q ^ (n.factorization q)))) 2 = 1;
              · exact h₂;
              · simp_all +decide [ Finset.sum_apply' ];
                exact absurd h_val2 ( by rw [ Finset.sum_eq_zero fun p hp => Nat.eq_zero_of_not_pos fun h => h₂ p ( Nat.prime_of_mem_primeFactors hp ) ( Nat.dvd_of_mem_primeFactors hp ) hodd.pos.ne' <| by linarith [ show ( Nat.factorization ( ArithmeticFunction.sigma 1 ( p ^ n.factorization p ) ) ) 2 ≤ 1 from Nat.le_of_not_lt fun h => by have := h_val2 ▸ Finset.single_le_sum ( fun x _ => Nat.zero_le ( Nat.factorization ( ArithmeticFunction.sigma 1 ( x ^ n.factorization x ) ) 2 ) ) hp; linarith ] ] ; norm_num );
            · aesop;
          -- Since $v_2(\sigma_1(q^{n.factorization q})) = 1$, we have that $n.factorization q$ is odd.
          have hq_odd : Odd (n.factorization q) := by
            contrapose! hq₂;
            simp_all +decide [ ArithmeticFunction.sigma_apply, Nat.factorization_eq_zero_of_not_dvd, ← even_iff_two_dvd, parity_simps ];
            rw [ Nat.factorization_eq_zero_of_not_dvd ] <;> norm_num [ Nat.dvd_iff_mod_eq_zero, Nat.add_mod, Nat.pow_mod, Finset.sum_nat_mod, Nat.odd_iff.mp ( hodd.of_dvd_nat hq₁.2.1 ), Nat.even_iff.mp hq₂ ];
          -- For any other prime factor $p$ of $n$, we have $v_2(\sigma_1(p^{n.factorization p})) = 0$.
          have hp_even : ∀ p ∈ n.primeFactors, p ≠ q → (Nat.factorization (ArithmeticFunction.sigma 1 (p ^ (n.factorization p)))) 2 = 0 := by
            intros p hp hpq
            have h_prod : (Nat.factorization (∏ p ∈ n.primeFactors, (ArithmeticFunction.sigma 1 (p ^ (n.factorization p))))) 2 = (∑ p ∈ n.primeFactors, (Nat.factorization (ArithmeticFunction.sigma 1 (p ^ (n.factorization p)))) 2) := by
              rw [ Nat.factorization_prod ];
              · rw [ Finset.sum_apply' ];
              · simp +contextual [ ArithmeticFunction.sigma ];
                exact fun x hx₁ hx₂ hx₃ => ⟨ 0, Nat.zero_le _, by aesop ⟩;
            rw [ Finset.sum_eq_add_sum_diff_singleton hq₁ ] at h_prod;
            exact Nat.eq_zero_of_le_zero ( by linarith [ Finset.single_le_sum ( fun x hx => Nat.zero_le ( ( sigma 1 ) ( x ^ n.factorization x ) |> Nat.factorization |> fun f => f 2 ) ) ( Finset.mem_sdiff.mpr ⟨ hp, by aesop ⟩ : p ∈ n.primeFactors \ { q } ) ] );
          refine' ⟨ q, Nat.prime_of_mem_primeFactors hq₁, Nat.dvd_of_mem_primeFactors hq₁, hq_odd, fun p hp₁ hp₂ hp₃ => _ ⟩;
          specialize hp_even p (by
          aesop) hp₃;
          simp_all +decide [ Nat.factorization_eq_zero_iff, ArithmeticFunction.sigma ];
          simp_all +decide [ Nat.even_iff, Nat.add_mod, Nat.pow_mod, Finset.sum_nat_mod ];
          cases Nat.Prime.eq_two_or_odd hp₁ <;> simp_all +decide [ Finset.sum_range_succ' ];
          · exact absurd ( even_iff_two_dvd.mpr hp₂ ) ( by simpa using hodd );
          · exact Nat.mod_two_ne_one.mp fun h => absurd ( hp_even.resolve_right fun h' => by have := h' 0 bot_le; aesop ) ( by omega );
        have hq₃ : q % 4 = 1 := by
          -- Since $q$ is odd and $a_q$ is odd, we have $σ₁(q^{a_q}) = (1 + q) * T$.
          have h_sigma_q : (ArithmeticFunction.sigma 1) (q ^ (n.factorization q)) = (1 + q) * (∑ i ∈ Finset.range ((n.factorization q + 1) / 2), q ^ (2 * i)) := by
            rcases Nat.even_or_odd' ( n.factorization q ) with ⟨ k, hk | hk ⟩ <;> simp_all +decide [ Nat.factorization_eq_zero_of_not_dvd, ← even_iff_two_dvd, parity_simps ];
            · grind +revert;
            · convert sigma_one_odd_exp_factor hq₁ using 1;
              norm_num [ Nat.add_div ];
          have hq_mod : ¬(4 ∣ (ArithmeticFunction.sigma 1) (q ^ (n.factorization q))) := by
            have h_sigma_prod : (ArithmeticFunction.sigma 1) n = (∏ p ∈ Nat.primeFactors n, (ArithmeticFunction.sigma 1) (p ^ (n.factorization p))) := by
              have h_sigma_prod : ∀ {m : ℕ}, m ≠ 0 → (ArithmeticFunction.sigma 1) m = (∏ p ∈ Nat.primeFactors m, (ArithmeticFunction.sigma 1) (p ^ (m.factorization p))) := by
                intros m hm_nonzero
                have h_sigma_prod : (ArithmeticFunction.sigma 1) m = (∏ p ∈ Nat.primeFactors m, (ArithmeticFunction.sigma 1) (p ^ (m.factorization p))) := by
                  have h_mul : ∀ {a b : ℕ}, a ≠ 0 → b ≠ 0 → Nat.Coprime a b → (ArithmeticFunction.sigma 1) (a * b) = (ArithmeticFunction.sigma 1) a * (ArithmeticFunction.sigma 1) b := by
                    simp +contextual [ ArithmeticFunction.sigma ];
                    exact?
                  conv_lhs => rw [ ← Nat.factorization_prod_pow_eq_self hm_nonzero ];
                  -- Apply the multiplicativity of the sum of divisors function to expand the product.
                  have h_expand : ∀ {S : Finset ℕ} {f : ℕ → ℕ}, (∀ p ∈ S, Nat.Prime p) → (ArithmeticFunction.sigma 1) (∏ p ∈ S, p ^ f p) = ∏ p ∈ S, (ArithmeticFunction.sigma 1) (p ^ f p) := by
                    intros S f hf; induction S using Finset.induction <;> simp_all +decide [ Nat.coprime_prod_right_iff, Nat.coprime_prod_left_iff ] ;
                    rw [ h_mul ( pow_ne_zero _ hf.1.ne_zero ) ( Finset.prod_ne_zero_iff.mpr fun p hp => pow_ne_zero _ ( Nat.Prime.ne_zero ( hf.2 p hp ) ) ) ];
                    · aesop;
                    · exact Nat.Coprime.prod_right fun p hp => Nat.Coprime.pow _ _ <| hf.1.coprime_iff_not_dvd.mpr fun h => ‹¬_› <| by have := Nat.prime_dvd_prime_iff_eq hf.1 ( hf.2 p hp ) ; aesop;
                  exact h_expand fun p hp => Nat.prime_of_mem_primeFactors hp;
                exact h_sigma_prod;
              exact h_sigma_prod hodd.pos.ne';
            have h_sigma_prod_odd : (∏ p ∈ Nat.primeFactors n \ {q}, (ArithmeticFunction.sigma 1) (p ^ (n.factorization p))) % 2 = 1 := by
