          · simp_all +decide [ ← Nat.dvd_iff_mod_eq_zero, hq₁.dvd_iff_eq ];
          · have := Nat.Prime.eq_two_or_odd hq₁; simp_all +decide [ ← Nat.mod_mod_of_dvd q ( by decide : 2 ∣ 4 ) ] ;
