            have h_val_q : padicValNat 2 (∏ p ∈ n.primeFactors, (ArithmeticFunction.sigma 1) (p ^ (n.factorization p))) = 1 := by
              have h_val_q : (∏ p ∈ n.primeFactors, (ArithmeticFunction.sigma 1) (p ^ (n.factorization p))) = 2 * n := by
                have h_sigma_prod : (ArithmeticFunction.sigma 1) n = ∏ p ∈ n.primeFactors, (ArithmeticFunction.sigma 1) (p ^ (n.factorization p)) := by
