/-! ## Euler's Shape Theorem -/

/-
**Euler's theorem on the shape of odd perfect numbers.**
If `n` is an odd perfect number, then there exist `q, k, m` such that:
- `q` is prime with `q ≡ 1 (mod 4)`,
- `n = q^(4k+1) · m²`, and
- `gcd(q, m) = 1`.
-/
theorem odd_perfect_euler_shape {n : ℕ}
    (hperf : Nat.Perfect n) (hodd : Odd n) :
    ∃ q k m : ℕ,
      Nat.Prime q ∧
      q % 4 = 1 ∧
      n = q ^ (4 * k + 1) * m ^ 2 ∧
      Nat.Coprime q m := by
        -- By `odd_perfect_unique_special_prime`, we know there exists a prime `q` with `q ≡ 1 (mod 4)` and exponent `4k+1`.
        obtain ⟨q, hq_prime, hq_mod4, hq_exp⟩ : ∃ q : ℕ, q.Prime ∧ q % 4 = 1 ∧ (n.factorization q) % 4 = 1 ∧ (∀ p : ℕ, p.Prime → p ≠ q → (n.factorization p) % 2 = 0) := by
          have := odd_perfect_unique_special_prime hperf hodd;
          obtain ⟨ q, hq₁, hq₂, hq₃, hq₄, hq₅ ⟩ := this; use q; refine' ⟨ hq₁, hq₃, hq₄, fun p hp hpq => _ ⟩ ; by_cases hpq' : p ∣ n <;> simp_all +decide [ Nat.factorization_eq_zero_of_not_dvd ] ;
        -- Write `n` as `q^(n.factorization q) * m^2` using the unique factorization theorem.
        obtain ⟨k, m, hm₁, hm₂⟩ : ∃ k m, n = q ^ (4 * k + 1) * m^2 ∧ Nat.Coprime q m := by
          obtain ⟨m, hm₁, hm₂⟩ : ∃ m, n = q ^ (n.factorization q) * m^2 ∧ Nat.Coprime q m := by
            apply coprime_sq_of_factorization;
            · grind +suggestions;
            · assumption;
            · exact hq_exp.2;
          exact ⟨ n.factorization q / 4, m, hm₁.trans ( by rw [ ← hq_exp.1, Nat.div_add_mod ] ), hm₂ ⟩;
        exact ⟨ q, k, m, hq_prime, hq_mod4, hm₁, hm₂ ⟩
